from django.db import migrations, models


def reprendre_caracteristiques(apps, schema_editor):
    """Régime et zone tendue passent du lot au bien ; chauffage et eau chaude : individuel / collectif d'après le texte."""
    Lot = apps.get_model("patrimoine", "Lot")
    for lot in Lot.objects.select_related("bien"):
        bien = lot.bien
        modifie = False
        if lot.regime_juridique and not bien.regime_juridique:
            bien.regime_juridique, modifie = lot.regime_juridique, True
        if lot.zone_tendue and not bien.zone_tendue:
            bien.zone_tendue, modifie = True, True
        if modifie:
            bien.save()
        for texte, mode, choix in (("chauffage", "mode_chauffage", ("individuel", "collectif")),
                                   ("eau_chaude", "mode_eau_chaude", ("individuelle", "collective"))):
            valeur = (getattr(lot, texte) or "").strip()
            for c in choix:
                if valeur.lower().startswith(c[:7]):
                    setattr(lot, mode, c)
                    setattr(lot, texte, valeur[len(c):].strip(" ,-:") if valeur.lower().startswith(c) else valeur)
        lot.save()


